"""Coastlines of the north-west Pacific for the article maps (longitude 126-172 E, latitude 19-52 N).

Source: Natural Earth, ne_50m_land (public domain: https://www.naturalearthdata.com/about/terms-of-use/), clipped to the box above, rounded to 0.1 degree and thinned
(Douglas-Peucker 0.12 degree).  Islands smaller than 0.05 square degree (the Ogasawara islands, for one) are not drawn; an article marks such a place with a point of its own.
The data is geography, not news and not mall data: it may live in the public repository.
Format: rings separated by a semicolon; each ring = first longitude and latitude in tenths of a degree, then the steps (dx, dy) in tenths of a degree.
"""
EXTENT = (126.0, 172.0, 19.0, 52.0)       # lon0, lon1, lat0, lat1
_ENC = "1432,520,6,-17,9,-16,-7,6,-9,-1,-5,-14,6,-10,3,0,1,-4,-1,-3,-2,5,-7,1,-5,-8,-2,8,2,5,-1,4,2,4,-3,8,3,8,-1,11,1,5,-5,8;1445,440,3,0,6,4,-3,-6,2,-3,1,-2,5,1,-4,-2,-15,-3,-6,-5,-1,-4,-14,6,-9,-2,-5,2,-2,-2,1,-2,8,-4,-5,0,-5,-4,-2,1,1,4,-2,7,6,4,0,4,8,-2,5,15,-1,7,3,1,9,-8,9,-6,3,0;1414,411,1,-5,5,-7,0,-4,-5,-11,-5,-2,0,-11,-4,-8,3,-6,-4,-2,-1,-3,-5,-3,0,4,2,3,-2,1,-2,-3,1,-2,-5,1,-4,-7,-1,5,-2,0,-4,-5,-11,0,2,2,-3,1,-1,-2,-1,4,-2,-4,3,-2,0,-2,-5,-1,-7,-7,-2,1,-3,4,-1,3,3,3,-6,2,-16,-5,-8,1,-2,-5,-4,2,-9,-1,1,4,5,1,14,10,11,0,12,3,1,-2,6,0,2,2,0,3,6,7,2,6,5,1,-5,-3,2,-4,12,4,11,10,4,6,3,6,-1,5,-2,0,2,4,-1,3,4,3,0,3,4,0,1,-3,5,1,-1,3,-4,-1,1,3,6,-1,-1,-1;1347,340,1,-2,-5,-2,-1,-3,-5,2,-4,-1,-4,-6,-4,1,-1,6,-3,-1,9,7,5,-1,2,1,-1,2,5,1,6,-1,0,-2;1315,336,2,0,-1,-3,3,0,1,-4,-4,-5,-2,-10,-3,1,0,-2,-4,-3,1,7,-2,-1,0,-4,-4,2,1,1,-1,6,5,5,-2,1,1,2,-3,3,-1,-2,2,-3,-3,1,-3,-2,1,2,-2,2,3,-1,-4,5,3,-1,0,2,8,5,7,-4;1548,497,1,-3,-2,-1,-1,1;1555,501,-2,0,-1,2,5,1,4,4,0,-3,-6,-3;1498,459,8,3,-10,-6,1,3;1479,450,-2,0,-8,-6,10,10,3,-1,7,2,-1,-2,-8,-2;1465,444,-9,-5,0,-2,-1,2,6,6,4,-1;1280,265,-3,-4,2,6,2,0,2,2,0,-2,-2,-1;1383,379,2,4,1,-2,-3,-2;1262,333,7,2,-2,-2,-4,0;1583,520,-15,-10,-3,10,-151,0,-4,-4,-5,-8,1,-7,-1,-2,-1,-9,-3,-6,-7,-5,-17,-21,-18,-14,-4,-5,-15,-9,-8,-3,-9,2,0,4,-2,-2,-2,0,1,2,-3,-1,-4,-5,-6,0,2,-2,-2,-2,-7,-3,-3,-4,0,-7,-21,-11,-2,-6,10,-5,10,-14,0,-12,2,-1,-5,-9,-6,0,0,-2,-8,1,0,-3,-3,1,0,-3,-2,1,1,2,-7,-5,-3,4,3,1,-2,0,-1,4,5,7,-3,8,-3,1,3,2,4,-2,1,2,-2,2,-1,6,-7,1,0,141"


def rings() -> list[list[tuple[float, float]]]:
    out = []
    for r in _ENC.split(";"):
        v = [int(x) for x in r.split(",")]
        if len(v) % 2:
            v = v[:-1]
        pts = [(v[0], v[1])]
        for i in range(2, len(v), 2):
            pts.append((pts[-1][0] + v[i], pts[-1][1] + v[i + 1]))
        out.append([(x / 10, y / 10) for x, y in pts])
    return out
